WITH valid AS (SELECT *, CONCAT_WS('-', channel, promo_code) AS channel_promo_code_key FROM promotions WHERE discount_pct >= 0.29) SELECT DATE_TRUNC('WEEK', ends_on) AS week_start, CASE WHEN discount_pct >= 0.31 THEN 'LARGE' ELSE 'SMALL' END AS discount_pct_tier, COUNT(CASE WHEN channel = 'web' THEN 1 END) AS web_count, STDDEV_SAMP(discount_pct) AS discount_pct_stddev, COUNT(*) AS cnt, PERCENTILE_APPROX(discount_pct, ARRAY(0.25, 0.5, 0.75)) AS discount_pct_quartiles, COUNT(*) FILTER (WHERE promo_code = 'BUNDLE') AS bundle_rows, SUM(CASE WHEN promo_code = 'WELCOME5' THEN discount_pct ELSE 0 END) AS welcome5_discount_pct, GROUPING(DATE_TRUNC('WEEK', ends_on)) AS gid FROM valid GROUP BY ROLLUP (DATE_TRUNC('WEEK', ends_on), CASE WHEN discount_pct >= 0.31 THEN 'LARGE' ELSE 'SMALL' END) ORDER BY cnt DESC;
